  ] as const).map((v) => (
    <button
      key={v.id}
      onClick={() => setActiveView(v.id)}
      className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors flex items-center gap-1.5 ${
        activeView === v.id
          ? "bg-card text-foreground shadow-sm"
          : "text-muted-foreground hover:text-foreground"
      }`}
    >
      {v.icon} {v.label}
    </button>
  ))}
</div>
```

### 4d. Replace the content rendering (the `{activeView === "assets" ? ... : activeView === "entities" ? ... : ...}` block) with:
```tsx
{activeView === "workshop" ? (
  <EntitiesView
    projectId={projectId}
