        onClick={() => onJump?.("assets-entities")}
        className="mt-2 px-4 py-2 rounded-lg bg-primary text-primary-foreground text-sm font-medium hover:bg-primary/90"
      >
        Go to Workshop
      </button>
    </div>
  );
}

